package org.genhttp.modules.clientcaching.validation

import org.genhttp.api.content.Concern
import org.genhttp.api.content.ConcernBuilder
import org.genhttp.api.content.Handler

/**
 * Builds a concern that tags the content generated by the server with ETags.
 */
public class CacheValidationBuilder : ConcernBuilder {

    override fun build(content: Handler): Concern = CacheValidationHandler(content)

}
